CREATE TABLE IF NOT EXISTS destinations (id TEXT PRIMARY KEY, display_name TEXT NOT NULL, city TEXT NOT NULL, state TEXT, country TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS packages (id TEXT PRIMARY KEY, destination_id TEXT, city TEXT NOT NULL, title TEXT NOT NULL, price_paise INTEGER NOT NULL CHECK(price_paise>=0), duration_days INTEGER NOT NULL CHECK(duration_days BETWEEN 1 AND 30));
CREATE TABLE IF NOT EXISTS package_components (id TEXT PRIMARY KEY, package_id TEXT NOT NULL, title TEXT NOT NULL, price_delta INTEGER NOT NULL, is_swappable INTEGER NOT NULL CHECK(is_swappable IN(0,1)));
CREATE TABLE IF NOT EXISTS guides (id TEXT PRIMARY KEY, city TEXT NOT NULL, display_name TEXT NOT NULL, language TEXT NOT NULL, specialization TEXT NOT NULL, rating REAL NOT NULL CHECK(rating BETWEEN 0 AND 5), price_paise INTEGER NOT NULL CHECK(price_paise>=0));
CREATE TABLE IF NOT EXISTS trips (id TEXT PRIMARY KEY, origin TEXT NOT NULL, destination TEXT NOT NULL, depart_date TEXT NOT NULL, return_date TEXT NOT NULL, travellers INTEGER NOT NULL CHECK(travellers BETWEEN 1 AND 8), budget_paise INTEGER NOT NULL CHECK(budget_paise BETWEEN 500000 AND 50000000), language TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS trip_items (trip_id TEXT NOT NULL, kind TEXT NOT NULL, ref_id TEXT NOT NULL, label TEXT NOT NULL, price_paise INTEGER NOT NULL CHECK(price_paise>=0), PRIMARY KEY(trip_id,kind));
CREATE TABLE IF NOT EXISTS negotiations (id TEXT PRIMARY KEY, trip_id TEXT NOT NULL, kind TEXT NOT NULL, item_label TEXT NOT NULL, proposed_price_paise INTEGER NOT NULL, overage_paise INTEGER NOT NULL CHECK(overage_paise>0), resolved INTEGER NOT NULL DEFAULT 0);
